import 'failure/failure.dart';

/// AD-12 — generic fetch-lifecycle state for screens with exactly one data
/// source and one fetch (`idle` / `loading` / `data` / `error`).
///
/// Used only where that shape fits (e.g. a single `GET` on screen entry).
/// RF02's capture pipeline, RF04's chat stream and RF07's composite
/// auth × sync × data state each define their own sealed state class instead
/// — never forced into this one (AD-12).
sealed class Resource<T> {
  const Resource();
}

final class ResourceIdle<T> extends Resource<T> {
  const ResourceIdle();
}

final class ResourceLoading<T> extends Resource<T> {
  const ResourceLoading();
}

final class ResourceData<T> extends Resource<T> {
  const ResourceData(this.data);

  final T data;
}

final class ResourceError<T> extends Resource<T> {
  const ResourceError(this.failure);

  final Failure failure;
}

import 'package:fpdart/fpdart.dart';

import 'failure/failure.dart';

/// AD-13 — the never-throws wrapper RF08 and RF10 both need for a side
/// effect that must never block or crash its caller, even on failure.
///
/// Typed stub only: the real implementation ships with RF10 (delivery
/// order's first consumer, per the architecture spine), not built
/// speculatively here in F000. RF10 may `await` it; RF08 must be able to
/// call it fire-and-forget (without awaiting).
typedef IsolatedSideEffect<T> = Future<Either<Failure, T>> Function(
  Future<T> Function() action,
);

/// Placeholder implementation — throws until RF10 replaces it.
Future<Either<Failure, T>> isolatedSideEffect<T>(
  Future<T> Function() action,
) {
  throw UnimplementedError(
    'isolatedSideEffect is a typed stub (AD-13) — implemented in RF10.',
  );
}

