98	            final isLogin = state.mode == AuthMode.login;
99	            final isSubmitting = state.isSubmitting;
100	
101	            // Both fields get the error border on a form-level failure
102	            // (AUTH_INVALID/network); the message itself is shown once,
103	            // under senha. `errorText: ''` on e-mail is border-only
104	            // (app_text_field.dart's documented convention).
105	            final emailErrorText = state.emailError ??
106	                (state.formError != null ? '' : null);
107	
108	            return SingleChildScrollView(
109	              padding: DesignTokens.screenPadding,
110	              child: Column(
111	                crossAxisAlignment: CrossAxisAlignment.stretch,
112	                mainAxisSize: MainAxisSize.min,
