117	                    textAlign: TextAlign.center,
118	                    style: DesignTokens.textHeadlineMd.copyWith(
119	                      color: DesignTokens.colorTextPrimary,
120	                    ),
121	                  ),
122	                  const SizedBox(height: DesignTokens.spacingLg),
123	                  AppTextField(
124	                    controller: _emailController,
125	                    labelText: 'E-mail',
126	                    keyboardType: TextInputType.emailAddress,
127	                    textInputAction: TextInputAction.next,
128	                    errorText: emailErrorText,
129	                    onChanged: cubit.emailChanged,
130	                  ),
131	                  const SizedBox(height: DesignTokens.spacingMd),
132	                  AppTextField(
133	                    controller: _passwordController,
134	                    focusNode: _passwordFocus,
135	                    labelText: 'Senha',
136	                    obscureText: true,
137	                    textInputAction: TextInputAction.done,
138	                    errorText: state.formError,
139	                    onChanged: cubit.passwordChanged,
140	                  ),
141	                  const SizedBox(height: DesignTokens.spacingLg),
142	                  AppButton(
143	                    label: isSubmitting
144	                        ? (isLogin ? 'Entrando…' : 'Criando conta…')
145	                        : (isLogin ? 'Entrar' : 'Criar conta'),
146	                    onPressed: isSubmitting ? null : cubit.submit,
147	                  ),
