408	/// Pure local validators (RNF06/07) — no `flutter` import, no network call.
409	/// Tela 0.1a blocks submit locally on a malformed email *before* any round
410	/// trip (epics.md Story 1.3 AC).
411	library;
412	
413	/// Deliberately permissive-but-structural: `local@domain.tld` shape, no
414	/// backend round trip required to catch an obviously malformed address.
415	final RegExp _emailShape = RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$');
416	
417	/// Returns a Portuguese inline error message, or `null` when [value] is a
418	/// structurally valid email.
419	String? validateEmail(String value) {
420	  final trimmed = value.trim();
421	  if (trimmed.isEmpty || !_emailShape.hasMatch(trimmed)) {
422	    return 'E-mail inválido';
423	  }
424	  return null;
425	}
426	
427	/// Returns a Portuguese inline error message, or `null` when [value] is a
428	/// non-empty password. The backend contract requires only `minLength: 1` —
429	/// no further local strength rule is invented (docs/input is silent).
430	String? validatePassword(String value) {
431	  if (value.isEmpty) {
432	    return 'Senha obrigatória';
433	  }
434	  return null;
435	}
