446	/// Drives Tela 0.1a. Calls [AuthRepository] directly (no use-case — Code Map:
447	/// this story's scope is small enough that an extra indirection layer isn't
448	/// justified yet); a BLoC/Cubit constructor never takes another BLoC/Cubit as
449	/// a dependency (architecture spine), so this takes the repository port.
450	class AuthCubit extends Cubit<AuthState> {
451	  AuthCubit(this._authRepository) : super(const AuthState());
452	
453	  final AuthRepository _authRepository;
454	
455	  /// Toggles login/signup — same screen, not a navigation (epics.md Story
456	  /// 1.3 AC). Keeps whatever the user already typed; clears any error from
457	  /// the previous mode's attempt.
458	  void toggleMode() {
459	    emit(
460	      AuthState(
461	        mode: state.mode == AuthMode.login ? AuthMode.signUp : AuthMode.login,
462	        email: state.email,
463	        password: state.password,
464	      ),
465	    );
466	  }
467	
468	  void emailChanged(String value) {
469	    emit(
470	      state.copyWith(
471	        email: value,
472	        clearEmailError: true,
473	        clearFormError: true,
474	      ),
475	    );
476	  }
477	
478	  void passwordChanged(String value) {
479	    emit(state.copyWith(password: value, clearFormError: true));
480	  }
481	
482	  /// Validates locally first — a malformed email (or empty password) blocks
483	  /// submit *before* any round trip (epics.md Story 1.3 AC). Only once local
484	  /// validation passes does it call `auth-signup`/`auth-login` with exactly
485	  /// `{email, password}`, saving the access token (via the repository) before
486	  /// this resolves.
487	  Future<void> submit() async {
488	    if (state.isSubmitting) {
489	      return;
490	    }
491	
492	    final emailError = validateEmail(state.email);
493	    if (emailError != null) {
494	      emit(
495	        state.copyWith(emailError: emailError, clearFormError: true),
496	      );
497	      return;
498	    }
499	
500	    final passwordError = validatePassword(state.password);
501	    if (passwordError != null) {
502	      emit(
503	        state.copyWith(formError: passwordError, clearEmailError: true),
504	      );
505	      return;
506	    }
507	
508	    emit(
509	      state.copyWith(
510	        status: const ResourceLoading<Unit>(),
511	        clearEmailError: true,
512	        clearFormError: true,
513	      ),
514	    );
515	
516	    final result = state.mode == AuthMode.login
517	        ? await _authRepository.logIn(
518	            email: state.email,
519	            password: state.password,
520	          )
521	        : await _authRepository.signUp(
522	            email: state.email,
523	            password: state.password,
524	          );
525	
526	    result.match(
527	      (failure) => emit(
528	        state.copyWith(
529	          status: const ResourceIdle<Unit>(),
530	          formError: failure.message,
531	        ),
532	      ),
533	      (_) => emit(state.copyWith(status: const ResourceData<Unit>(unit))),
534	    );
535	  }
536	}
