1008	/// Collects every state the cubit emits for the duration of [act], since the
1009	/// stack has no `bloc_test` pin — this drives [AuthCubit] through its public
1010	/// API only (never the `@protected` `emit`), the same way any other
1011	/// `flutter_bloc` consumer would.
1012	Future<List<AuthState>> _emittedDuring(
1013	  AuthCubit cubit,
1014	  Future<void> Function() act,
1015	) async {
1016	  final emitted = <AuthState>[];
1017	  final subscription = cubit.stream.listen(emitted.add);
1018	  await act();
1019	  // `submit()`'s awaited repository call resolves its mocked Future on a
1020	  // microtask; `Future.delayed(Duration.zero)` only resumes once the whole
1021	  // microtask queue (including the stream's event dispatch to our
1022	  // listener) has drained, so this reliably waits for every emit `act()`
1023	  // triggered before we stop listening.
1024	  await Future<void>.delayed(Duration.zero);
1025	  await subscription.cancel();
1026	  return emitted;
1027	}
